figure.artwork:
VARWOF-AIC DEFINITIONS { iso(1) identified-organization(3) dod(6) internet(1) private(4) enterprise(1) varwof(66257) modules(2) id-mod-varwof-aic(1) } DEFINITIONS ::= BEGIN
-- All SEQUENCEs SHALL use DER encoding (ordered, no indefinite-length). -- See RFC 5912 Sec. 3 for DER encoding rules. -- Implementations MUST reject BER indefinite-length encodings.
IMPORTS EXTENSION FROM PKIX-CommonTypes-2009 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkixCommonTypes-02(57) }, AlgorithmIdentifier FROM PKIXAlgs-2009 { iso(1) identified-organization(3) dod(6) internet(1) security(5) mechanisms(5) pkix(7) id-mod(0) id-mod-pkix1-algorithms2008-02(56) } ;
-- OID Assignments
id-varwof OBJECT IDENTIFIER ::= { 1 3 6 1 4 1 66257 } id-aic OBJECT IDENTIFIER ::= { id-varwof 1 1 }
-- AIC Extension
aicExt EXTENSION ::= { SYNTAX AIC IDENTIFIED BY id-aic CRITICAL FALSE }
AIC ::= SEQUENCE { version INTEGER DEFAULT 1, agentId UTF8String (SIZE(1..256)), principalUid PrincipalUid, capabilities SEQUENCE SIZE(1..MAX) OF Capability, delegationMode DelegationMode DEFAULT authorized, authorizationConstraints [0] EXPLICIT SEQUENCE SIZE(0..32) OF Capability OPTIONAL, delegationAuthorization DelegationAuthorization, extensions [1] EXPLICIT AICExtensions OPTIONAL }
DelegationMode ::= INTEGER { authorized (0), representative (1) } (0..1)
PrincipalUid ::= SEQUENCE { version INTEGER (0..255) DEFAULT 1, realm UTF8String (SIZE(1..128)), identifier UTF8String (SIZE(1..256)), keyHash OCTET STRING (SIZE(1..64)), hashAlgo [0] EXPLICIT AlgorithmIdentifier OPTIONAL } -- hashAlgo omitted defaults to SHA-256 (OID 2.16.840.1.101.3.4.2.1); -- keyHash = hashAlgo(SPKI). Only hash algorithms with output length -- not exceeding 64 bytes are supported (SHA-2/SHA-3 family, SM3, -- BLAKE2/BLAKE3). keyHash length is determined by the algorithm.
Capability ::= SEQUENCE { schemeId UTF8String (SIZE(1..128)), capabilityId UTF8String (SIZE(1..256)), parameters [0] EXPLICIT OCTET STRING (SIZE(0..4096)) OPTIONAL }
-- Reason for delegation authorization (mandatory in -- DelegationAuthorization / DelegationAuthTBS; not present in -- PrincipalAuthorization)
Reason ::= SEQUENCE { reasonCode UTF8String (SIZE(1..64)), -- controlled vocabulary, e.g., SCHEDULED_MAINTENANCE description UTF8String (SIZE(1..512)) -- human-readable description }
DelegationAuthorization ::= SEQUENCE { reason Reason, requestedLifetime INTEGER (1..86400), -- SHOULD 3600-86400 timestamp GeneralizedTime, -- MUST be UTC (Z form) nonce OCTET STRING (SIZE(32)), signatureAlgorithm AlgorithmIdentifier, signatureValue OCTET STRING }
-- DelegationAuthTBS (To-Be-Signed structure) -- The principal's private key signs the DER encoding of this structure.
DelegationAuthTBS ::= SEQUENCE { version INTEGER { v1(1), v2(2) } DEFAULT v1, agentId UTF8String (SIZE(1..256)), principalUid PrincipalUid, reason Reason, capabilities SEQUENCE SIZE(1..MAX) OF Capability, delegationMode DelegationMode, authorizationConstraints [0] EXPLICIT SEQUENCE SIZE(0..32) OF Capability OPTIONAL, requestedLifetime INTEGER (1..86400), -- SHOULD 3600-86400 timestamp GeneralizedTime, -- MUST be UTC (Z) nonce OCTET STRING (SIZE(32)), agentKeyBinding [1] EXPLICIT AgentKeyBinding OPTIONAL }
-- Version/validation matrix (normative): -- version = 1 (legacy): agentKeyBinding MUST be absent; -- version = 2 (current): agentKeyBinding MUST be present and valid; -- any other version value: rejected. -- Newly issued DAs MUST be version 2.
AgentKeyBinding ::= SEQUENCE { keyHash OCTET STRING (SIZE(1..64)), hashAlgo [0] EXPLICIT AlgorithmIdentifier OPTIONAL } -- Binds the DA to the agent's public key: keyHash = hashAlgo(SPKI DER), -- hashAlgo omitted defaults to SHA-256 (OID 2.16.840.1.101.3.4.2.1). -- Only hash algorithms whose output does not exceed 64 octets are -- supported (SHA-2/SHA-3 family, SM3, BLAKE2/BLAKE3); keyHash length -- MUST equal the declared algorithm's output length. An unknown or -- unsupported hashAlgo MUST be rejected (no silent fallback); SHA-1 -- MUST NOT be used.
-- PrincipalAuthorization Extension (OID: 1.3.6.1.4.1.66257.1.2) -- Carried in the Principal's certificate.
paExt EXTENSION ::= { SYNTAX PrincipalAuthorization IDENTIFIED BY id-principal-auth CRITICAL FALSE } id-principal-auth OBJECT IDENTIFIER ::= { id-varwof 1 2 }
PrincipalAuthorization ::= SEQUENCE { version INTEGER DEFAULT 1, grants SEQUENCE SIZE(1..MAX) OF Capability, authorizationConstraints [0] EXPLICIT SEQUENCE SIZE(0..32) OF Capability OPTIONAL, delegationPolicy [1] EXPLICIT DelegationPolicy OPTIONAL, extensions [2] EXPLICIT AICExtensions OPTIONAL }
DelegationPolicy ::= SEQUENCE { version INTEGER DEFAULT 1, maxAgents INTEGER DEFAULT 1, allowedMode DelegationModeEnum DEFAULT authorizedOnly, maxSessionHours [0] EXPLICIT INTEGER OPTIONAL }
DelegationModeEnum ::= INTEGER { authorizedOnly (0), representativeAllowed (1) } (0..1)
-- Extensibility Framework
AICExtensions ::= SEQUENCE SIZE (1..MAX) OF ExtField
ExtField ::= SEQUENCE { extnID OBJECT IDENTIFIER, critical BOOLEAN DEFAULT FALSE, extnValue OCTET STRING }
-- DelegationDepthControl carries the delegation chain depth. -- Placed in AIC extensions slot, OID 1.3.6.1.4.1.66257.1.1.4. -- chainDepth MUST NOT exceed maxDepth. -- This revision defines semantics for chainDepth = 0 and chainDepth = 1 -- only. Deeper chains are not refused, but they are outside the scope -- of this specification; a deployment that uses them does so under its -- own policy and cannot claim conformance for them.
id-ddc OBJECT IDENTIFIER ::= { id-aic 4 } DelegationDepthControl ::= SEQUENCE { chainDepth INTEGER (0..255), -- OID .1.1.4.1 maxDepth INTEGER (0..255) -- OID .1.1.4.2 }
END

AIC ::= {
    agentId         "agent-1",
    principalUid    {
        realm       "corp.com",
        identifier  "zhangsan",
        keyHash     <32-byte hash of the principal's SPKI>
    },
    capabilities    {
        { schemeId "http", capabilityId "GET:/api/v1/users" }
    },
    delegationAuthorization {
        reason      {
            reasonCode  "SCHEDULED_MAINTENANCE",
            description "temporary maintenance window"
        },
        requestedLifetime 3600,
        timestamp   "2026-08-18T00:00:00Z",
        nonce       <32-byte CSPRNG value>,
        signatureAlgorithm ecdsa-with-SHA256,
        signatureValue <DER-encoded signature over DelegationAuthTBS>
    }
}

list.t:
version = 1 (legacy): agentKeyBinding MUST be absent; a
version-1 TBS carrying the binding is malformed and MUST be
rejected;

figure.artwork:
PrincipalAuthorization ::= SEQUENCE {
    version                  INTEGER DEFAULT 1,
    grants                   SEQUENCE SIZE(1..MAX) OF Capability,
    authorizationConstraints [0] EXPLICIT SEQUENCE
        SIZE(0..32) OF Capability OPTIONAL,
    delegationPolicy         [1] EXPLICIT DelegationPolicy OPTIONAL,
    extensions               [2] EXPLICIT AICExtensions OPTIONAL
}

DelegationPolicy ::= SEQUENCE {
    version             INTEGER DEFAULT 1,
    maxAgents           INTEGER DEFAULT 1,
    allowedMode         DelegationModeEnum DEFAULT authorizedOnly,
    maxSessionHours     [0] EXPLICIT INTEGER OPTIONAL
}

DelegationModeEnum ::= INTEGER {
    authorizedOnly        (0),
    representativeAllowed (1)
} (0..1)

list.t:
Certificate revocation (CRL/OCSP) is the only mechanism available
to signal that a principal no longer authorizes a given agent;
revocation does not erase the certificate itself.

https://github.com/varwof/types -- shared types, including the AIC
extension structures and the AIC-JWT core (Apache-2.0),
release v0.6.0;

https://github.com/varwof/gateway-core and
https://github.com/varwof/gateway -- zero-trust gateways
(Apache-2.0), gateway-core release v0.5.0 and gateway release v0.1.0;

Single-machine ceiling: approximately 6,100 AIC certificates/s
(8,040/s with turbo boost), dominated by ECDSA signing and
DelegationAuthorization verification;

Worst-case burst: 500,000 simultaneous issuance requests drain in
approximately 82 s with no dropped requests when the in-memory
engine budget is sized accordingly;
